import React, { useState } from 'react';
import axios from 'axios';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';

const API = 'http://localhost:8000';

interface Message {
  role: 'user' | 'assistant';
  content: string;
  domain?: string;
  imageUrl?: string;
  enhancedPrompt?: string;
  mapHtml?: string;
  stockChart?: string;
}

function normalizeMarkdown(content: string): string {
  return content.replace(/<br\s*\/?>(\s*)/gi, '\n$1');
}

function App() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);

  const sendMessage = async () => {
    if (!input.trim()) return;

    const userMsg: Message = { role: 'user', content: input };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setLoading(true);

    try {
      const res = await axios.post(`${API}/api/chat`, { message: input });
      const aiMsg: Message = {
        role: 'assistant',
        content: typeof res.data.output === 'string' ? res.data.output : 'Response received.',
        domain: res.data.domain,
        imageUrl: res.data.image_url,
        enhancedPrompt: res.data.enhanced_prompt,
        mapHtml: res.data.map_html,
        stockChart: res.data.stock_chart
      };
      setMessages(prev => [...prev, aiMsg]);
    } catch (err) {
      setMessages(prev => [...prev, {
        role: 'assistant',
        content: 'Error occurred. Please try again.',
        domain: 'general'
      }]);
    }
    setLoading(false);
  };

  const domainColors: Record<string, string> = {
    research: 'bg-blue-900 text-blue-300',
    stock:    'bg-green-900 text-green-300',
    code:     'bg-yellow-900 text-yellow-300',
    job:      'bg-purple-900 text-purple-300',
    flight:   'bg-cyan-900 text-cyan-300',
    image:    'bg-pink-900 text-pink-300',
    general:  'bg-gray-800 text-gray-300',
  };

  return (
    <div className="flex h-screen bg-gray-950 text-white">

      {/* Sidebar */}
      <div className="w-56 bg-gray-900 border-r border-gray-800 flex flex-col">
        <div className="p-4 border-b border-gray-800">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-900 rounded-lg flex items-center justify-center text-lg">🤖</div>
            <div>
              <div className="font-semibold text-sm">MAIA</div>
              <div className="text-xs text-gray-500">Multi-agent AI</div>
            </div>
            <div className="ml-auto w-2 h-2 rounded-full bg-green-500"></div>
          </div>
        </div>
        <div className="p-3">
          <button
            onClick={() => setMessages([])}
            className="w-full py-2 px-3 bg-blue-600 hover:bg-blue-700 rounded-lg text-sm transition"
          >
            ✚ New Chat
          </button>
        </div>
        <div className="p-3 flex-1">
          <div className="text-xs text-gray-600 uppercase tracking-wider mb-2 px-1">Pipelines</div>
          {['🔬 Research','📈 Stock','💻 Code','💼 Job','✈️ Flight','🎨 Image','💬 General'].map(p => (
            <div key={p} className="flex items-center gap-2 px-2 py-1.5 text-sm text-gray-400 hover:text-white hover:bg-gray-800 rounded cursor-pointer transition">
              {p}
            </div>
          ))}
        </div>
        <div className="p-3 border-t border-gray-800">
          <div className="text-xs text-gray-600 text-center">7 agents online</div>
        </div>
      </div>

      {/* Main */}
      <div className="flex-1 flex flex-col">

        {/* Top bar */}
        <div className="flex items-center gap-3 px-6 py-3 border-b border-gray-800 bg-gray-900">
          <div className="font-semibold">MAIA</div>
          <div className="text-gray-600 text-sm">|</div>
          <div className="text-gray-400 text-sm">Multi-agent intelligence system</div>
          <div className="ml-auto flex gap-2">
            <span className="text-xs px-3 py-1 rounded-full bg-green-900 text-green-300 border border-green-800">✓ 92% accuracy</span>
            <span className="text-xs px-3 py-1 rounded-full bg-blue-900 text-blue-300 border border-blue-800">⚡ 7 pipelines</span>
          </div>
        </div>

        {/* Pipeline tabs */}
        <div className="flex gap-2 px-6 py-2 border-b border-gray-800 bg-gray-900 flex-wrap">
          {['🔬 Research','📈 Stock','💻 Code','💼 Job','✈️ Flight','🎨 Image','💬 General'].map(tab => (
            <div key={tab} className="px-3 py-1 text-xs rounded-full border border-gray-700 text-gray-500 cursor-default">
              {tab}
            </div>
          ))}
        </div>

        {/* Chat area */}
        <div className="flex-1 overflow-y-auto p-6 space-y-4">
          {messages.length === 0 && (
            <div className="flex flex-col items-center justify-center h-full text-center">
              <div className="text-5xl mb-4">🤖</div>
              <h1 className="text-2xl font-bold mb-2">Welcome to MAIA</h1>
              <p className="text-gray-400 mb-6">Your Multi-Agent Intelligence Assistant</p>
              <div className="grid grid-cols-2 gap-3 max-w-lg">
                {[
                  "What are latest LLM advancements?",
                  "Analyse AAPL stock",
                  "Track flight AI102",
                  "Review my Python code"
                ].map(q => (
                  <button
                    key={q}
                    onClick={() => setInput(q)}
                    className="p-3 bg-gray-800 hover:bg-gray-700 rounded-xl text-sm text-left text-gray-300 border border-gray-700 transition"
                  >
                    {q}
                  </button>
                ))}
              </div>
            </div>
          )}

          {messages.map((msg, i) => (
            <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start gap-3'}`}>
              {msg.role === 'assistant' && (
                <div className="w-7 h-7 bg-green-900 rounded-lg flex items-center justify-center text-sm flex-shrink-0 mt-1">🤖</div>
              )}
              <div className={`max-w-2xl ${msg.role === 'user' ? 'bg-blue-900 border border-blue-800 rounded-2xl rounded-br-sm px-4 py-2.5 text-blue-100' : ''}`}>
                {msg.role === 'assistant' && msg.domain && (
                  <div className={`inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded-full mb-2 ${domainColors[msg.domain] || 'bg-gray-800 text-gray-400'}`}>
                    {msg.domain} pipeline
                  </div>
                )}
                <div className={msg.role === 'assistant' ? 'markdown-content bg-gray-800 border border-gray-700 rounded-2xl rounded-tl-sm px-4 py-3 text-gray-200 text-sm leading-relaxed whitespace-pre-wrap' : 'text-sm'}>
                  {msg.role === 'assistant' ? (
                    <ReactMarkdown remarkPlugins={[remarkGfm]}>
                      {normalizeMarkdown(msg.content)}
                    </ReactMarkdown>
                  ) : (
                    msg.content
                  )}
                </div>
                {msg.imageUrl && (
                  <img
                    src={msg.imageUrl}
                    alt={msg.enhancedPrompt || 'Generated image'}
                    className="mt-3 max-w-full rounded-xl border border-gray-700"
                  />
                )}
                {msg.stockChart && (
                  <iframe
                    title="Stock chart"
                    srcDoc={msg.stockChart}
                    className="visual-frame mt-3"
                  />
                )}
                {msg.mapHtml && (
                  <iframe
                    title="Flight map"
                    srcDoc={msg.mapHtml}
                    className="visual-frame mt-3"
                  />
                )}
              </div>
            </div>
          ))}

          {loading && (
            <div className="flex gap-3">
              <div className="w-7 h-7 bg-green-900 rounded-lg flex items-center justify-center text-sm">🤖</div>
              <div className="bg-gray-800 border border-gray-700 rounded-2xl rounded-tl-sm px-4 py-3">
                <div className="flex gap-1">
                  <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce"></div>
                  <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce" style={{animationDelay:'0.1s'}}></div>
                  <div className="w-2 h-2 bg-gray-500 rounded-full animate-bounce" style={{animationDelay:'0.2s'}}></div>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Input */}
        <div className="p-4 border-t border-gray-800 bg-gray-900">
          <div className="flex gap-3 max-w-4xl mx-auto">
            <input
              type="text"
              value={input}
              onChange={e => setInput(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && sendMessage()}
              placeholder="Ask anything — 7 agents ready..."
              className="flex-1 bg-gray-800 border border-gray-700 rounded-2xl px-5 py-3 text-sm text-white placeholder-gray-500 focus:outline-none focus:border-blue-600 transition"
            />
            <button
              onClick={sendMessage}
              disabled={loading}
              className="w-11 h-11 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 rounded-full flex items-center justify-center transition"
            >
              ↑
            </button>
          </div>
        </div>

      </div>
    </div>
  );
}

export default App;
